#!/data/data/com.termux/files/usr/bin/env bash
# =============================================================================
#  install-omniroute.sh - ONE-FILE, hands-free installer for the OmniRoute
#  stack on Android (Termux). This single file embeds everything: the three
#  web bridges, the Cookie Pusher extension, the start/boot scripts, autostart
#  wiring, and battery hardening. Run it once and you are done - the stack
#  auto-starts on every phone boot (Termux:Boot) and every time you open
#  Termux. You never re-run this.
#
#  Quick start (ONE line of typing, no decisions):
#    1. Install Termux + Termux:Boot from F-Droid (NOT Play Store).
#    2. Get this file onto the phone (WhatsApp) next to omniroute-transfer.tar.gz.
#    3. In Termux paste:
#         termux-setup-storage && cd ~/storage/downloads && bash install-omniroute.sh
#       That is the WHOLE setup: it installs the LEAN default (gateway + all
#       chat routes + the extension, ~1.5GB) and auto-imports the transfer tar
#       (your sessions, kit + Claude persona + pickers + MCPs) if it is nearby.
#    4. Remaining one-time taps: load the extension in Kiwi, push sessions,
#       open Termux:Boot once, Battery -> Unrestricted (script prints steps).
#
#  Storage: the default install is MINIMAL (~1.5GB): nodejs + the gateway +
#  the mimo-web bridge + the Cookie Pusher extension. Every chat route works
#  (zai/qwen/deepseek/lmarena/mimo/gemini-web via pushed cookies). The heavy
#  extras are OPT-IN: chromium (~1GB incl. deps) for Google Flow images and
#  the gemini bridge build (rust/clang, ~1.5GB, stripped by SAVE_SPACE=1).
#
#  Options (env vars, all optional - defaults are already the lean choice):
#    FULL=1    install EVERYTHING: chromium (FLOW=1) + gemini bridge
#              (GEMINI=1). Expect ~5-6GB total; runs with SAVE_SPACE=1.
#    FLOW=1    add Chromium (~1GB incl. deps) + the Google Flow image bridge.
#    GEMINI=1  add the gemini bridge build (rust/clang, ~1.5GB while building).
#    SAVE_SPACE=1  strip rust/clang/make + caches after the gemini build (~1GB).
#    UPDATE=1  force a gateway npm update even if omniroute is installed.
#    FORCE=1   re-extract the embedded bridges/extension (normally kept).
#
#  It is 100% safe to re-run at any time: every step is idempotent, nothing
#  is wiped or duplicated.
# =============================================================================
set -euo pipefail

FLOW="${FLOW:-0}"
INSTALL_DIR=~/omniroute-android
OMHOME=~/.omniroute
LOG_DIR="$OMHOME/logs"
PAYLOAD_B64=""

say() { echo; echo "==> $*"; }
ok()  { echo "    ok: $*"; }

# ---------------------------------------------------------------- clean mode
# bash install-omniroute.sh clean  ->  full teardown: kills the stack, deletes
# all state (gateway DB, sessions, kit, Claude/Codex configs, caches), removes
# the boot/bashrc autostart hooks and uninstalls the heavy packages (rust,
# clang, chromium, node, python). Termux itself and your Download/ files stay.
if [ "${1:-}" = "clean" ]; then
  echo "==> OmniRoute complete cleanup..."
  # Kill the stack processes. NOTE: never match bare 'omniroute' here - this
  # script's own filename contains it and pkill -f would kill the installer
  # itself mid-cleanup. Match the actual service command lines instead.
  pkill -f 'omniroute serve|start-omniroute|gemini-bridge|mimo-web|flow-browser|omniroute-android' 2>/dev/null || true
  sleep 1
  command -v termux-wake-lock >/dev/null 2>&1 && termux-wake-lock -r 2>/dev/null || true
  rm -rf "$INSTALL_DIR" ~/omniroute-cookie-pusher "$OMHOME" ~/.claude ~/.codex ~/.cargo ~/.npm ~/.cache ~/.shortcuts
  rm -f ~/.termux/boot/omniroute-boot.sh
  sed -i '/omniroute/d' ~/.bashrc 2>/dev/null || true
  for p in rust clang make chromium nodejs-lts python; do
    pkg uninstall -y "$p" >/dev/null 2>&1 || true
  done
  pkg clean -y >/dev/null 2>&1 || true
  echo "    cleaned. free space now:"
  df -h "$PREFIX" | tail -1
  echo "    (your Download/ files are untouched - reinstall with:  bash install-omniroute.sh)"
  exit 0
fi

# ---------------------------------------------------------------- [1/10] deps
say "[0/10] Storage preflight + auto-decisions..."
FREE_MB=$(df -Pk "$PREFIX" 2>/dev/null | awk 'NR==2{print int($4/1024)}')
# Lean by default: the minimal install needs ~1.5GB. FULL=1 opts into the
# heavy extras (chromium ~1GB, gemini build ~1.5GB). FLOW/GEMINI can also be
# set directly for finer control (e.g. FLOW=1 GEMINI=0 for Flow images only).
FLOW="${FLOW:-0}"
GEMINI="${GEMINI:-0}"
SAVE_SPACE="${SAVE_SPACE:-0}"
if [ "${FULL:-0}" = "1" ]; then
  FLOW=1; GEMINI=1; SAVE_SPACE=1
  echo "    FULL=1 - enabling chromium (~1GB) + gemini build (~1.5GB); expect ~5-6GB total"
fi
if [ -n "$FREE_MB" ] && [ "$FREE_MB" -lt 2000 ]; then
  echo "    ~${FREE_MB}MB free - tight: build tools will be stripped after the gemini build (SAVE_SPACE=1)"
  SAVE_SPACE=1
fi
if [ -n "$FREE_MB" ] && [ "$FLOW" = "1" ] && [ "$FREE_MB" -lt 1200 ]; then
  echo "    ~${FREE_MB}MB free - low: auto-skipping chromium (~1GB); flowui images disabled"
  FLOW=0
fi
if [ -n "$FREE_MB" ] && [ "$GEMINI" = "1" ] && [ "$FREE_MB" -lt 1000 ]; then
  echo "    ~${FREE_MB}MB free - very low: also skipping the gemini bridge build (no rust compile)"
  GEMINI=0
fi
echo "    install profile: FLOW=$FLOW (chromium) GEMINI=$GEMINI (gemini bridge) - minimal ~1.5GB, full ~5-6GB"

say "[1/10] Updating Termux packages (first run takes a few minutes)..."
# Noninteractive: dpkg conffile prompts (openssl.cnf, sources.list, bashrc,
# profile) would otherwise block a hands-free run waiting for a Y/N keypress.
# --force-confdef/--force-confold keeps the installed config silently.
export DEBIAN_FRONTEND=noninteractive
DPKG_OPTS='-o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold'
pkg update -y >/dev/null 2>&1 || pkg update -y
pkg upgrade -y $DPKG_OPTS >/dev/null 2>&1 || pkg upgrade -y $DPKG_OPTS

# python is only needed for the gemini bridge (GEMINI=1) - the lean profile
# skips it (~100MB saved).
PKGS="nodejs-lts git binutils"
[ "$GEMINI" = "1" ] && PKGS="$PKGS python"
say "[2/10] Installing runtimes ($PKGS)..."
if ! pkg install -y $PKGS >/dev/null 2>&1; then
  echo; echo "FATAL: could not install Termux runtimes (nodejs-lts). Check your" >&2
  echo "internet connection, then re-run:  bash install-omniroute.sh" >&2
  exit 1
fi
ok "runtimes ready"

# ----------------------------------------------------------------- [3/10] chromium
if [ "$FLOW" = "1" ] && ! command -v chromium >/dev/null 2>&1; then
  say "[3/10] Installing Chromium for the Google Flow image bridge (x11-repo + tur-repo, ~1GB incl. deps; the lean default skips this - FLOW=0)..."
  # chromium needs BOTH repos: x11-repo provides its deps (gtk3, libevdev,
  # libxkbcommon) and tur-repo provides chromium itself. Then a package
  # refresh so both indexes are loaded before installing (the classic
  # "Depends: gtk3 but it is not installable" / "cannot locate" failures).
  # Space guard: chromium + deps need ~800MB during install, so below ~1.2GB
  # free it is not attempted (it would starve the gateway + gemini steps
  # that follow).
  if [ -n "$FREE_MB" ] && [ "$FREE_MB" -lt 1200 ]; then
    echo "    (only ~${FREE_MB}MB free - chromium needs ~1GB; flowui images disabled)"
    echo "     Free some space, then:  pkg install -y x11-repo tur-repo && pkg update && pkg install -y chromium"
  else
    # Termux has NO /tmp - using it silently killed the install (the redirect
    # failed, so pkg never ran). $PREFIX/tmp always exists here.
    CHROME_LOG="$PREFIX/tmp/omni-chromium.log"
    pkg install -y x11-repo tur-repo >/dev/null 2>&1 || true
    pkg update -y >/dev/null 2>&1 || pkg update -y
    if ! pkg install -y chromium >"$CHROME_LOG" 2>&1; then
      # ~250MB download - a transient network/repo failure is common on
      # phones. Clean the package cache and retry once before giving up.
      echo "    (first attempt failed - cleaning package cache and retrying once)"
      pkg clean >/dev/null 2>&1 || true
      pkg update -y >/dev/null 2>&1 || true
      pkg install -y chromium >"$CHROME_LOG" 2>&1 || true
    fi
    if command -v chromium >/dev/null 2>&1; then
      ok "chromium installed"
    else
      echo "    (chromium failed - flowui images disabled; chat routes unaffected)"
      echo "     Last error lines from pkg:"
      tail -8 "$CHROME_LOG" 2>/dev/null | sed 's/^/       /' || true
      echo "     Retry after install:  pkg install -y x11-repo tur-repo && pkg update && pkg install -y chromium"
    fi
  fi
else
  if command -v chromium >/dev/null 2>&1; then
    say "[3/10] Chromium already installed"
  else
    say "[3/10] Chromium skipped (FLOW=0)"
  fi
fi

# ------------------------------------------------------------------ [4/10] gateway
say "[4/10] Installing the omniroute gateway (npm)..."
if command -v omniroute >/dev/null 2>&1 && [ "${UPDATE:-0}" != "1" ]; then
  ok "omniroute already installed - skipping (UPDATE=1 to force)"
else
  if ! npm install -g --no-audit --no-fund omniroute@latest; then
    echo; echo "FATAL: could not install the omniroute gateway (npm install failed)." >&2
    echo "Check your internet connection, then re-run:  bash install-omniroute.sh" >&2
    exit 1
  fi
  ok "omniroute installed"
fi

# --------------------------------------------------------------------- [5/10] .env
say "[5/10] Writing ~/.omniroute/.env ..."
mkdir -p "$OMHOME" "$LOG_DIR"
if [ ! -f "$OMHOME/.env" ]; then
  KEY=$(node -e "console.log(require('crypto').randomBytes(32).toString('hex'))")
  # The zai captcha worker ships inside the npm package; locate it (npm root -g
  # fallback covers pkg-manager differences).
  WORKER="$(npm root -g 2>/dev/null)/omniroute/dist/.build/next/server/zai-captcha-worker.js"
  [ -f "$WORKER" ] || WORKER="$(command -v omniroute >/dev/null 2>&1 && dirname "$(dirname "$(command -v omniroute)")")/lib/node_modules/omniroute/dist/.build/next/server/zai-captcha-worker.js"
  cat > "$OMHOME/.env" <<EOF
# generated by install-omniroute.sh on $(date -Iseconds)
PORT=20128
HOST=0.0.0.0
STORAGE_ENCRYPTION_KEY=$KEY
ZAI_CAPTCHA_WORKER=$WORKER
EOF
  ok ".env written (fresh encryption key)"
else
  ok ".env already exists - keeping it (delete it to regenerate)"
fi

# ---------------------------------------------------------------- [6/10] payload
say "[6/10] Extracting bridges + extension (embedded in this file)..."
if [ ! -d "$INSTALL_DIR/bridge" ] || [ "${FORCE:-0}" = "1" ]; then
  mkdir -p "$INSTALL_DIR"
  if ! echo "$PAYLOAD_B64" | base64 -d | tar xz -C "$INSTALL_DIR"; then
    echo; echo "FATAL: embedded payload extraction failed (this file is corrupted or" >&2
    echo "was truncated). Download install-omniroute.sh again and re-run it." >&2
    exit 1
  fi
  chmod +x "$INSTALL_DIR/start-omniroute.sh" "$INSTALL_DIR/boot.sh" "$INSTALL_DIR/fix-model-cache.sh" 2>/dev/null || true
  ok "extracted to $INSTALL_DIR"
else
  # Keep existing bridges/config, but ALWAYS refresh the launcher + picker-sync
  # scripts (idempotent - lets a re-run of a NEW installer pick up fixes like
  # the chromium tur-repo refresh and fix-model-cache.sh).
  if ! echo "$PAYLOAD_B64" | base64 -d | tar xz -C "$INSTALL_DIR" start-omniroute.sh boot.sh fix-model-cache.sh; then
    echo "    (script refresh failed - continuing with existing files)"
  fi
  chmod +x "$INSTALL_DIR/start-omniroute.sh" "$INSTALL_DIR/boot.sh" "$INSTALL_DIR/fix-model-cache.sh" 2>/dev/null || true
  ok "already extracted - launcher scripts refreshed (FORCE=1 to re-extract everything)"
fi

# ---------------------------------------------------------------- [7/10] bridge deps
say "[7/10] Installing bridge dependencies..."
if [ "$FLOW" != "1" ]; then
  echo "    (flow-browser deps skipped - FLOW=0; set FLOW=1 and re-run to enable Google Flow images)"
elif [ -d "$INSTALL_DIR/bridge/flow-browser" ]; then
  # PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD=1: the bridge drives the system chromium
  # via CHROME_PATH, so the ~200MB bundled browser download is pure waste.
  ( cd "$INSTALL_DIR/bridge/flow-browser" && PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD=1 npm install --omit=dev --no-audit --no-fund >/dev/null 2>&1 ) \
    && ok "flow-browser deps (playwright + MCP SDK, no browser download)" \
    || echo "    (flow-browser deps failed - flowui may not start)"
fi
if [ "$GEMINI" != "1" ]; then
  echo "    (gemini bridge skipped - GEMINI=0; set GEMINI=1 and re-run the installer when you have space)"
elif [ -d "$INSTALL_DIR/bridge/gemini-bridge" ]; then
  # gemini_webapi 2.1.0 needs pydantic-core + orjson (Rust) and curl_cffi.
  # No prebuilt Android wheels exist for pydantic-core/orjson, so the first
  # attempt may fail - install Rust + set ANDROID_API_LEVEL (maturin cannot
  # auto-detect it on Termux; device SDK, fallback 24) and retry. The pinned
  # pydantic 2.12 supports Termux's Python 3.14 (older cores use removed FFI).
  if ( cd "$INSTALL_DIR/bridge/gemini-bridge" && pip install --no-cache-dir -r requirements.txt >/dev/null 2>&1 ); then
    if python -c "import gemini_webapi" >/dev/null 2>&1; then
      ok "gemini-bridge deps (gemini_webapi)"
    else
      # The curl_cffi android abi3 wheel hard-links libpython3.13.so, which
      # cannot load on Termux python 3.14 (bionic resolves the dependency
      # differently than a direct dlopen, so a symlink does NOT help). Rebuild
      # curl_cffi from source against the local python - links 3.14 instead.
      echo "    (curl_cffi abi3 wheel broken on python 3.14 - rebuilding from source)"
      pkg install -y clang make >/dev/null 2>&1 || true
      if pip install --no-cache-dir --force-reinstall --no-binary curl_cffi "curl_cffi==0.16.0" >/dev/null 2>&1 \
        && python -c "import gemini_webapi" >/dev/null 2>&1; then
        ok "curl_cffi rebuilt for python 3.14 - gemini bridge ready"
      else
        echo "    (gemini deps still broken - run manually:"
        echo "     pkg install clang make && pip install --force-reinstall --no-binary curl_cffi curl_cffi==0.16.0)"
      fi
    fi
  else
    echo "    (gemini-bridge deps failed - installing rust for native builds, then retrying)"
    pkg install -y rust >/dev/null 2>&1 || true
    export ANDROID_API_LEVEL="${ANDROID_API_LEVEL:-$(getprop ro.build.version.sdk 2>/dev/null || echo 24)}"
    if ( cd "$INSTALL_DIR/bridge/gemini-bridge" && pip install --no-cache-dir -r requirements.txt >/dev/null 2>&1 ); then
      ok "gemini-bridge deps after rust install"
    else
      echo "    (gemini-bridge deps still failed - gflow may not start; run manually:"
      echo "     pkg install rust && export ANDROID_API_LEVEL=\\$(getprop ro.build.version.sdk)"
      echo "     && cd $INSTALL_DIR/bridge/gemini-bridge && pip install -r requirements.txt)"
    fi
  fi
fi
ok "mimo-web bridge needs no deps (pure Node)"

# --------------------------------------------------------------- [8/10] extension
say "[8/10] Installing the Cookie Pusher extension for Kiwi..."
if [ -d "$INSTALL_DIR/extension" ]; then
  mkdir -p ~/omniroute-cookie-pusher
  cp -r "$INSTALL_DIR/extension/." ~/omniroute-cookie-pusher/
  cat > ~/omniroute-cookie-pusher/config.js <<'EOF'
// Generated by install-omniroute.sh - local admin token for OmniRoute.
// To rotate: omniroute tokens create --name "Cookie Pusher" --scope admin
export const DEFAULT_URL = 'http://127.0.0.1:20128';
export const DEFAULT_API_KEY = 'omniroute';

// Local cookie bridges (mimo-web-bridge on 20135) - cookies are pushed here
// directly instead of into a gateway connection.
export const BRIDGE_URL = 'http://127.0.0.1:20135';
EOF
  ok "extension at ~/omniroute-cookie-pusher"
  # Kiwi cannot browse Termux's private storage - put a copy on shared storage.
  say "Copying the extension to shared storage for Kiwi..."
  # NEVER call termux-setup-storage here: it opens an interactive Android
  # permission dialog and can hang the installer forever waiting for a tap.
  # The installer is normally launched from ~/storage/downloads, so storage
  # is already granted - just check accessibility and copy. If the extension
  # is already on /sdcard (nothing wrong), skip the copy entirely.
  if [ -f /sdcard/omniroute-cookie-pusher/manifest.json ] \
     && [ -f /sdcard/omniroute-cookie-pusher/config.js ]; then
    # refresh the generated config in place (token/paths may have changed)
    cp ~/omniroute-cookie-pusher/config.js /sdcard/omniroute-cookie-pusher/config.js 2>/dev/null || true
    ok "extension already at /sdcard/omniroute-cookie-pusher - skipping copy"
  elif [ -d /sdcard ]; then
    if timeout 15 cp -r ~/omniroute-cookie-pusher /sdcard/omniroute-cookie-pusher 2>/dev/null; then
      ok "extension also at /sdcard/omniroute-cookie-pusher (load THIS in Kiwi)"
    else
      echo "    (storage not writable - after granting storage (termux-setup-storage), run:"
      echo "     cp -r ~/omniroute-cookie-pusher /sdcard/)"
    fi
  else
    echo "    (no /sdcard yet - after granting storage (termux-setup-storage), run:"
    echo "     cp -r ~/omniroute-cookie-pusher /sdcard/)"
  fi
else
  echo "    WARN: extension payload missing from this file"
fi

# ---------------------------------------------------------------- [9/10] autostart
say "[9/10] Wiring autostart (Termux:Boot + open-Termux hook)..."
mkdir -p ~/.termux/boot
cp "$INSTALL_DIR/boot.sh" ~/.termux/boot/omniroute-boot.sh
chmod +x ~/.termux/boot/omniroute-boot.sh
if ! grep -q "omniroute-android/start-omniroute.sh" ~/.bashrc 2>/dev/null; then
  cat >> ~/.bashrc <<'EOF'

# OmniRoute: auto-start the stack when Termux opens (no-op if already running)
if [ -x ~/omniroute-android/start-omniroute.sh ]; then
  ( ~/omniroute-android/start-omniroute.sh >/dev/null 2>&1 & )
fi
EOF
fi
ok "Termux:Boot script + ~/.bashrc hook installed"

# --- Termux:Widget shortcuts (install Termux:Widget from F-Droid, then
#     long-press the home screen -> Widgets -> Termux:Widget) ---
mkdir -p ~/.shortcuts
cat > ~/.shortcuts/omniroute-status <<'EOF'
#!/data/data/com.termux/files/usr/bin/env bash
for p in 20128 20133 20134 20135; do
  (echo >/dev/tcp/127.0.0.1/$p) >/dev/null 2>&1 && echo "$p UP" || echo "$p down"
done
EOF
cat > ~/.shortcuts/omniroute-restart <<'EOF'
#!/data/data/com.termux/files/usr/bin/env bash
bash ~/omniroute-android/start-omniroute.sh
EOF
chmod +x ~/.shortcuts/omniroute-status ~/.shortcuts/omniroute-restart
ok "Termux:Widget shortcuts (omniroute-status / omniroute-restart)"

# --------------------------------------------------------------- [10/10] battery
say "[10/10] Battery hardening (best-effort)..."
if command -v termux-wake-lock >/dev/null 2>&1; then
  termux-wake-lock && ok "wake lock held (install termux-api from F-Droid if missing)"
fi
cmd appops set com.termux RUN_IN_BACKGROUND allow >/dev/null 2>&1 \
  && ok "RUN_IN_BACKGROUND allowed for Termux" \
  || echo "    (appops needs a one-time Android grant - Settings will prompt)"
dumpsys deviceidle whitelist +com.termux >/dev/null 2>&1 \
  && ok "Doze whitelist: com.termux" \
  || echo "    (deviceidle needs adb - use Settings -> Battery -> Unrestricted instead)"

# ------------------------------------------------------------------- start
say "Starting the stack now (first cold start may take a minute)..."
bash "$INSTALL_DIR/start-omniroute.sh" || true

# --------------------------------------------------------------- [11/10] space
# Cache purging ALWAYS runs (npm/pip/pkg caches can quietly eat 500MB+);
# the build toolchains (rust/clang/make, only ever installed for GEMINI=1)
# are removed when SAVE_SPACE=1.
say "[11/10] Storage cleanup - purging npm/pip/pkg caches..."
npm cache clean --force >/dev/null 2>&1 || true
rm -rf ~/.npm/_cacache 2>/dev/null || true
pip cache purge >/dev/null 2>&1 || true
pkg clean -y >/dev/null 2>&1 || true
echo "    free space now:"; df -h "$PREFIX" | tail -1
if [ "${SAVE_SPACE:-0}" = "1" ]; then
  say "    SAVE_SPACE=1 - also removing build toolchains (rust/clang/make)..."
  # rust/clang/make are ONLY needed to compile pydantic-core/orjson/curl_cffi;
  # the built wheels are already installed, so the toolchains can go (~1GB).
  pkg uninstall -y rust clang make 2>/dev/null | tail -1 || true
  rm -rf ~/.cargo 2>/dev/null || true
  echo "    free space now:"; df -h "$PREFIX" | tail -1
  ok "build tools removed (reclaim ~1GB); set GEMINI=1 on a re-run to rebuild"
fi

# -------------------------------------------------------------- [12/10] transfer
# If omniroute-transfer.tar.gz (made by make-transfer.sh on the PC) is next to
# the installer, import it automatically: sessions + combos + kit + Claude
# persona + pickers + MCP servers. Zero extra typing.
TAR_FOUND=""
for cand in \
  "$(dirname "$0")/omniroute-transfer.tar.gz" \
  ~/storage/downloads/omniroute-transfer.tar.gz \
  ~/storage/downloads/WhatsApp/omniroute-transfer.tar.gz \
  /sdcard/Download/omniroute-transfer.tar.gz \
  /sdcard/Download/WhatsApp/omniroute-transfer.tar.gz; do
  if [ -f "$cand" ]; then TAR_FOUND="$cand"; break; fi
done
if [ -n "$TAR_FOUND" ]; then
  say "[12/10] Transfer found ($TAR_FOUND) - importing sessions, kit + Claude persona..."
  echo "$PAYLOAD_B64" | base64 -d | tar xz -C "$INSTALL_DIR" import-transfer.sh 2>/dev/null || true
  if [ ! -f "$INSTALL_DIR/import-transfer.sh" ]; then
    tar xzf "$TAR_FOUND" -C "$INSTALL_DIR" import-transfer.sh 2>/dev/null || true
  fi
  if [ -f "$INSTALL_DIR/import-transfer.sh" ]; then
    bash "$INSTALL_DIR/import-transfer.sh" "$TAR_FOUND"
  else
    echo "    (import-transfer.sh missing - import later:  tar xzf omniroute-transfer.tar.gz import-transfer.sh && bash import-transfer.sh omniroute-transfer.tar.gz)"
  fi
else
  echo "    (no omniroute-transfer.tar.gz found next to the installer - session import skipped."
  echo "     Send it later and run:  tar xzf omniroute-transfer.tar.gz import-transfer.sh && bash import-transfer.sh omniroute-transfer.tar.gz)"
fi

# ----------------------------------------------------------- [13/10] self-check
# End-to-end verification of the final state (after the transfer import, which
# restarts the stack): all 4 ports, the gateway's /v1/models route list, and
# the picker sync. Prints a PASS/WARN/FAIL summary. Never fails the install -
# a FAIL here just tells you exactly what to fix.
say "[13/10] End-to-end self-check (ports, gateway, pickers)..."
SELF_PORT="$(grep -E '^PORT=' "$OMHOME/.env" 2>/dev/null | head -1 | cut -d= -f2 | tr -d ' \"' || true)"
SELF_PORT="${SELF_PORT:-20128}"
port_up() { (echo >/dev/tcp/127.0.0.1/"$1") >/dev/null 2>&1; }
# the import restart may still be cold-starting the gateway - give it time
if ! port_up "$SELF_PORT"; then
  echo "    waiting for gateway on $SELF_PORT (up to 90s)..."
  for _ in $(seq 1 90); do
    port_up "$SELF_PORT" && break
    sleep 1
  done
fi
PASS=0; WARN=0; FAIL=0
for p in "$SELF_PORT" 20133 20134 20135; do
  if port_up "$p"; then
    echo "    port $p : UP"
    PASS=$((PASS+1))
  else
    case "$p" in
      "$SELF_PORT")
        echo "    port $p : DOWN (gateway - critical; see $LOG_DIR/gateway.log)"; FAIL=$((FAIL+1)) ;;
      20135)
        echo "    port $p : DOWN (mimo-web bridge - critical; see $LOG_DIR/gateway.log)"; FAIL=$((FAIL+1)) ;;
      20133)
        echo "    port $p : down (gflow - needs the gemini build; see $LOG_DIR/gemini.log)"; WARN=$((WARN+1)) ;;
      20134)
        echo "    port $p : down (flowui - needs chromium; images disabled, chat routes fine)"; WARN=$((WARN+1)) ;;
    esac
  fi
done
ROUTES=0
if port_up "$SELF_PORT"; then
  # 30s: the models list is ~1MB JSON on a slow phone link - 8s truncated it.
  ROUTES=$(curl -s -m 30 "http://127.0.0.1:$SELF_PORT/v1/models" 2>/dev/null \
    | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{try{console.log((JSON.parse(d).data||[]).length)}catch{console.log('0')}})" 2>/dev/null || echo 0)
fi
if [ "${ROUTES:-0}" -gt 0 ] 2>/dev/null; then
  echo "    gateway /v1/models : OK ($ROUTES routes)"
  PASS=$((PASS+1))
else
  echo "    gateway /v1/models : FAIL (no route list; gateway may still be starting - rerun the start script)"
  FAIL=$((FAIL+1))
fi
if [ -f "$LOG_DIR/pickers.log" ] && grep -q 'claude cache seeded' "$LOG_DIR/pickers.log" 2>/dev/null; then
  echo "    picker sync        : OK (routes seeded into Claude/Codex pickers)"
  PASS=$((PASS+1))
else
  echo "    picker sync        : not verified (rerun: bash ~/omniroute-android/fix-model-cache.sh)"
  WARN=$((WARN+1))
fi
echo
echo "    ============ SELF-CHECK SUMMARY ============"
echo "      PASS: $PASS    WARN: $WARN    FAIL: $FAIL"
if [ "$FAIL" -eq 0 ] && [ "$WARN" -eq 0 ]; then
  echo "      >>> ALL GOOD - the full stack is up: routes, bridges, pickers."
elif [ "$FAIL" -eq 0 ]; then
  echo "      >>> UP with warnings (see the 'down' lines above - chat routes still work)."
else
  echo "      >>> $FAIL critical check(s) failed - see the lines above and the referenced logs."
fi

cat <<'EOF'

==============================================================
 DONE - OmniRoute is running on this phone.
   Dashboard:    http://127.0.0.1:20128
   Other devices (same Wi-Fi): http://<phone-ip>:20128
     (find the phone IP: Wi-Fi settings, or `ifconfig` in Termux)

   Storage: this install used ~1.5-2GB (lean default). To add Google Flow
   images + the gemini bridge later:  FLOW=1 GEMINI=1 bash install-omniroute.sh
   (adds ~2.5GB - only do it when you have space to spare).

 ONE-TIME app setup (about 2 minutes, never again):
   1. Install Kiwi Browser -> chrome://extensions -> enable
      Developer mode -> "Load unpacked" -> /sdcard/omniroute-cookie-pusher
   2. Sign in on the sites you use (z.ai, chat.qwen.ai, deepseek.com,
      aistudio.xiaomimimo.com, arena.ai, gemini.google.com, ...) then open
      the Cookie Pusher extension -> Grab & push sessions.
   3. Open the Termux:Boot app once (arms boot autostart).
   4. Android Settings -> Apps -> Termux and Termux:Boot -> Battery ->
      Unrestricted (keeps the stack alive as a background service).
   5. (Optional) Install Termux:API (wake lock) and Termux:Widget (home-
      screen omniroute-status / omniroute-restart buttons) from F-Droid.
   6. (Optional) Battery-saver polling: run start with POWER_SAVE=1 so the
      stack suspends while the screen is off and wakes with it:
         POWER_SAVE=1 bash ~/omniroute-android/start-omniroute.sh

 After that: nothing to redo. It auto-starts on every boot and every time
 you open Termux. Cutting the internet never breaks the install - the local
 services keep running and routes just work again when the connection
 returns. If a provider ever expires your session, re-push it from Kiwi.
==============================================================
EOF
